const source=await import(uri);
const q=s=>"'"+s.replaceAll("'","''")+"'";
const schema='g1_review',owner='g1_review_owner',app='g1_review_app';
const grants=source.SERVING_FUNCTION_EXECUTE_GRANTS.map(x=>x.signature),denials=[...source.SERVING_FUNCTION_EXECUTE_DENIALS];
const all=[...grants,...denials];
const setup=[
'CREATE ROLE '+owner+' NOLOGIN;',
'CREATE ROLE '+app+' LOGIN NOINHERIT;',
'CREATE SCHEMA '+schema+' AUTHORIZATION '+owner+';',
'CREATE TABLE '+schema+'.participation_owners(id int);',
'ALTER TABLE '+schema+'.participation_owners OWNER TO '+owner+';',
'GRANT USAGE ON SCHEMA '+schema+' TO '+app+';',
...all.flatMap(signature=>[
'CREATE FUNCTION '+schema+'.'+signature+' RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog, '+schema+', pg_temp AS $body$ SELECT 1 $body$;',
'ALTER FUNCTION '+schema+'.'+signature+' OWNER TO '+owner+';',
'REVOKE ALL ON FUNCTION '+schema+'.'+signature+' FROM PUBLIC;']),
...grants.map(s=>'GRANT EXECUTE ON FUNCTION '+schema+'.'+s+' TO '+app+';'),
'GRANT '+owner+' TO '+app+' WITH INHERIT FALSE, SET TRUE;',
'SET SESSION AUTHORIZATION '+app+';'
].join('\n');
const sql=source.SERVING_FUNCTION_PRIVILEGES_SQL.replaceAll('$1',q(schema)).replaceAll('$2','ARRAY['+all.map(q).join(',')+']').replaceAll('$3','ARRAY['+all.map((_,i)=>i<grants.length?'true':'false').join(',')+']');
const statements=setup+'\nSELECT jsonb_agg(facts) FROM ('+sql+') facts;\n'+
'SELECT json_build_object('+q('immediate_owner_usage')+', pg_has_role(current_user,'+q(owner)+','+q('USAGE')+'), '+q('can_set_owner')+', pg_has_role(current_user,'+q(owner)+','+q('SET')+'));\n'+
'SET ROLE '+owner+';\nSELECT json_build_object('+q('after_set_role')+', current_user, '+q('formerly_denied_functions_executable')+', count(*) FILTER (WHERE has_function_privilege(current_user,to_regprocedure('+q(schema+'.')+' || signature),'+q('EXECUTE')+'))) FROM unnest(ARRAY['+denials.map(q).join(',')+']) signature;';
const r=spawnSync('docker',['exec','-i',input.container,'psql','-X','-q','-A','-t','-v','ON_ERROR_STOP=1','-U','postgres'],{input:statements,encoding:'utf8',maxBuffer:2*1024*1024});
if(r.status!==0)throw Error(r.stderr);
const parts=r.stdout.trim().split('\n').map(s=>JSON.parse(s));
const acceptedRole=source.assertServingFunctionPrivileges(parts[0]);
if(parts[1].immediate_owner_usage!==false||parts[1].can_set_owner!==true||parts[2].formerly_denied_functions_executable!==147)throw Error('Unexpected facts');
console.log(JSON.stringify({head:input.head,sourceBlob:input.source.sha,postgresImage:'postgres:17.11',preflightAcceptedRole:acceptedRole,preflightRowCount:parts[0].length,roleFacts:parts[1],afterSetRole:parts[2],result:'preflight admits a role that can SET ROLE to owner and execute all 147 denials',limits:'Disposable isolated local catalog fixture with all 170 reviewed signatures and exact fetched SQL/assertion. No product migrations, staging credentials or managed mutation.'}));
